<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import AppIcon from './AppIcon.vue'
import {useCampus} from '../stores/campus'
const props=defineProps<{open:boolean,dark:boolean}>(),emit=defineEmits<{close:[],saved:[]}>(),campus=useCampus()
const step=ref(0),keyword=ref(''),choices=ref<any[]>([]),building=ref<any>(null),floor=ref<any>(null),room=ref<any>(null),loading=ref(false),saving=ref(false),error=ref('')
let epoch=0
const titles=['选择楼栋','选择楼层','选择房间']
const filtered=computed(()=>choices.value.filter(x=>String(step.value===0?x.building:x.buildingname).toLowerCase().includes(keyword.value.trim().toLowerCase())))
const selectedName=computed(()=>room.value?`${building.value.building}舍 · ${floor.value.buildingname} · ${room.value.buildingname}`:'')
function close(){epoch++;emit('close')}
async function load(target:number){const id=++epoch;step.value=target;keyword.value='';choices.value=[];error.value='';loading.value=true;try{const values=await campus.rooms(['buildings','floors','rooms'][target],target===0?{}:{building:building.value.building,factorycode:building.value.factorycode,...(target===2?{floor_id:floor.value.buildingid}:{})});if(id===epoch)choices.value=values}catch(e){if(id===epoch)error.value=(e as Error).message}finally{if(id===epoch)loading.value=false}}
function pick(value:any){if(step.value===0){building.value=value;floor.value=null;room.value=null;load(1)}else if(step.value===1){floor.value=value;room.value=null;load(2)}else room.value=value}
function isPicked(value:any){return step.value===0?value.building===building.value?.building:step.value===1?value.buildingid===floor.value?.buildingid:value.buildingid===room.value?.buildingid}
function mainLabel(value:any){return String(step.value===0?value.building:value.buildingname).replace(/号房间|层|_/g,'')}
async function save(){if(!room.value||saving.value)return;saving.value=true;error.value='';try{await campus.bindRoom({building:building.value.building,factorycode:building.value.factorycode,floor_id:floor.value.buildingid,room_id:room.value.buildingid});emit('saved');close()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
watch(()=>props.open,value=>{if(value){building.value=null;floor.value=null;room.value=null;load(0)}else epoch++})
</script>
<template><view v-if="open" class="dorm-mask" :class="{dark}" @click="close"><view class="dorm-sheet" @click.stop><view class="dorm-handle"/><view class="dorm-title"><view class="dorm-title-icon"><AppIcon name="home" :size="36"/></view><view><text>宿舍电量</text><text class="dorm-subtitle">选择要查询的房间</text></view><view class="dorm-close" @click="close">×</view></view><view v-if="campus.roomBinding" class="dorm-current"><view class="dorm-dot"/><text>当前 · {{campus.roomBinding.room_name}}</text></view><view class="dorm-steps"><view :class="{active:step===0,done:step>0}" @click="load(0)"><text class="step-number">1</text><text>{{building?building.building+'舍':'楼栋'}}</text></view><text class="step-arrow">›</text><view :class="{active:step===1,done:step>1}" @click="building&&load(1)"><text class="step-number">2</text><text>{{floor?.buildingname||'楼层'}}</text></view><text class="step-arrow">›</text><view :class="{active:step===2}" @click="floor&&load(2)"><text class="step-number">3</text><text>房间</text></view></view><view class="dorm-search"><AppIcon name="search" :size="29"/><input v-model="keyword" :placeholder="step===0?'搜索楼栋，如 12':step===1?'搜索楼层':'搜索房间号'"/><view v-if="keyword" @click="keyword=''">×</view></view><view class="dorm-list-heading"><text>{{titles[step]}}</text><text>{{loading?'加载中':filtered.length+' 项'}}</text></view><scroll-view class="dorm-options" scroll-y><view v-if="loading" class="dorm-grid"><view v-for="i in 12" :key="i" class="dorm-skeleton"/></view><view v-else-if="error" class="dorm-empty" @click="load(step)"><AppIcon name="refresh" :size="44"/><text>{{error}}</text><text>点击重试</text></view><view v-else-if="!filtered.length" class="dorm-empty"><text>没有匹配的选项</text></view><view v-else class="dorm-grid"><view v-for="(option,i) in filtered" :key="i" class="dorm-option" :class="{picked:isPicked(option)}" @click="pick(option)"><text class="dorm-option-value">{{mainLabel(option)}}</text><text class="dorm-option-unit">{{step===0?'舍':step===1?'层':'号房间'}}</text><text v-if="isPicked(option)" class="dorm-check">✓</text></view></view></scroll-view><view class="dorm-footer"><view><text>{{selectedName||'请选择楼栋、楼层和房间'}}</text><text>{{room?'请核对房间号后绑定':'仅查询电量，不会发起缴费'}}</text></view><button :disabled="!room||saving" :loading="saving" @click="save">绑定房间</button></view></view></view></template>
<style scoped lang="scss">
.dorm-mask{--p:#fff;--ink:#18304f;--muted:#8b9bb0;--soft:#f3f7fc;--line:#e9eff7;position:fixed;inset:0;background:#07182b70;z-index:50;display:flex;align-items:flex-end;backdrop-filter:blur(7px)}.dark{--p:#1b2b44;--ink:#edf3ff;--muted:#98abc8;--soft:#243751;--line:#30445e}.dorm-sheet{width:100%;max-width:1000rpx;margin:0 auto;background:var(--p);color:var(--ink);border-radius:40rpx 40rpx 0 0;padding:14rpx 30rpx 0;box-shadow:0 -20rpx 80rpx #08162720}.dorm-handle{width:64rpx;height:7rpx;background:#a8b7ca44;border-radius:10rpx;margin:0 auto 25rpx}.dorm-title{display:flex;align-items:center;gap:17rpx;font-size:32rpx;font-weight:650}.dorm-title-icon{width:68rpx;height:68rpx;display:flex;align-items:center;justify-content:center;border-radius:21rpx;background:#eaf3ff}.dorm-subtitle{display:block;font-size:21rpx;color:var(--muted);font-weight:400;margin-top:5rpx}.dorm-close{margin-left:auto;width:55rpx;height:55rpx;border-radius:50%;background:var(--soft);color:var(--muted);font-size:35rpx;text-align:center;line-height:51rpx;font-weight:400}.dorm-current{display:flex;align-items:center;gap:10rpx;font-size:21rpx;color:#5887be;background:var(--soft);padding:16rpx 20rpx;border-radius:17rpx;margin-top:22rpx}.dorm-dot{height:8rpx;width:8rpx;background:#4a96f6;border-radius:50%}.dorm-steps{display:flex;align-items:center;gap:9rpx;margin:24rpx 0}.dorm-steps>view{display:flex;align-items:center;justify-content:center;gap:8rpx;flex:1;background:var(--soft);color:var(--muted);border:2rpx solid transparent;border-radius:17rpx;padding:17rpx 4rpx;font-size:22rpx}.dorm-steps .active{border-color:#86b9ff;background:#edf5ff;color:#287bf5;font-weight:600}.dorm-steps .done{color:#4288dc}.dark .dorm-steps .active{background:#244875}.step-number{font-size:18rpx;opacity:.65}.step-arrow{color:#a9b8ca;font-size:28rpx}.dorm-search{display:flex;align-items:center;gap:12rpx;background:var(--soft);padding:0 20rpx;height:75rpx;border-radius:20rpx;color:var(--muted)}.dorm-search input{flex:1;min-width:0;height:75rpx;font-size:25rpx;color:var(--ink)}.dorm-search>view{font-size:29rpx}.dorm-list-heading{display:flex;justify-content:space-between;font-size:23rpx;font-weight:600;margin:25rpx 3rpx 19rpx}.dorm-list-heading>text+text{font-size:20rpx;color:var(--muted);font-weight:400}.dorm-options{height:36vh;min-height:340rpx;max-height:640rpx}.dorm-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14rpx;padding:0 2rpx 18rpx}.dorm-option{position:relative;text-align:center;display:flex;align-items:center;justify-content:center;flex-direction:column;background:var(--soft);border:2rpx solid transparent;border-radius:20rpx;min-height:100rpx;padding:14rpx 4rpx}.dorm-option.picked{border-color:#5da0ff;background:#eaf3ff;color:#2379ed}.dark .dorm-option.picked{background:#28476f}.dorm-option-value{font-size:29rpx;font-weight:650;word-break:break-all}.dorm-option-unit{font-size:18rpx;color:var(--muted);margin-top:4rpx}.dorm-check{position:absolute;right:6rpx;top:3rpx;color:#287bf5;font-size:18rpx}.dorm-footer{border-top:1rpx solid var(--line);padding:22rpx 2rpx calc(24rpx + env(safe-area-inset-bottom));display:flex;align-items:center;gap:15rpx}.dorm-footer>view{flex:1;min-width:0}.dorm-footer text{display:block;font-size:23rpx;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dorm-footer text+text{font-size:19rpx;color:var(--muted);margin-top:8rpx}.dorm-footer button{background:#287bf5;color:white;border-radius:19rpx;font-size:24rpx;margin:0;padding:0 25rpx;height:77rpx;line-height:77rpx}.dorm-footer button[disabled]{background:var(--soft);color:var(--muted)}.dorm-empty{padding:60rpx 20rpx;display:flex;align-items:center;flex-direction:column;gap:15rpx;color:var(--muted);font-size:23rpx}.dorm-skeleton{height:105rpx;border-radius:20rpx;background:var(--soft)}
</style>
